:root {
  --room: #2b1f27;
  --room-light: #3b2b35;
  --room-deep: #1c1318;
  --lamp: #f4eadb;
  --lamp-bright: #f9f2e6;
  --lamp-deep: #e6d8c3;
  --ink: #2a1e23;
  --ink-2: #6f6066;
  --ink-3: #9d8f95;
  --on-room: #f4eadb;
  --on-room-2: rgba(244, 234, 219, 0.64);
  --on-room-3: rgba(244, 234, 219, 0.38);
  --veil: rgba(244, 234, 219, 0.08);
  --veil-2: rgba(244, 234, 219, 0.14);
  --chili: #d8412f;
  --chili-deep: #b7321f;
  --p1: #d98c9b;
  --p2: #e0a472;
  --p3: #9db58b;
  --p4: #8dafc7;
  --p5: #b39ac9;
  --p6: #d2b15a;
  --p7: #7fb3ae;
  --p8: #c98a78;
  --r-card: 28px;
  --r-control: 14px;
  --shadow-card:
    0 34px 60px -24px rgba(0, 0, 0, 0.6),
    0 0 110px -20px rgba(244, 234, 219, 0.14);
  --shadow-soft: 0 14px 30px -18px rgba(0, 0, 0, 0.5);
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--room-deep);
}

body {
  margin: 0;
  min-height: 100dvh;
  color: var(--on-room);
  background:
    radial-gradient(ellipse 130% 60% at 50% -12%, var(--room-light) 0%, var(--room) 48%, var(--room-deep) 100%)
      fixed;
  font-family: var(--font-body), "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:disabled {
  cursor: default;
  opacity: 0.55;
}

a {
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 2px solid var(--lamp);
  outline-offset: 3px;
}

.card :focus-visible,
.card-front :focus-visible {
  outline-color: var(--chili);
}

/* Shell */

.shell {
  width: min(440px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 16px calc(20px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
}

.topbar {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.wordmark {
  border: 0;
  padding: 0;
  background: none;
  font-family: var(--font-display), Georgia, serif;
  font-size: 1.15rem;
  color: var(--on-room);
}

.text-button {
  border: 0;
  padding: 8px 2px;
  background: none;
  font-size: 0.9rem;
  color: var(--on-room-2);
}

.text-button:hover {
  color: var(--on-room);
}

.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.screen-head {
  padding: 8px 0 26px;
}

.screen-head h1 {
  font-size: clamp(1.8rem, 7.6vw, 2.15rem);
  line-height: 1.12;
  color: var(--on-room);
}

.screen-head p {
  margin-top: 10px;
  color: var(--on-room-2);
  max-width: 34ch;
}

.steps {
  display: flex;
  gap: 6px;
  margin-bottom: 26px;
}

.steps span {
  flex: 1;
  height: 3px;
  border-radius: 2px;
  background: var(--on-room-3);
  transition: background 0.3s;
}

.steps span.done {
  background: var(--on-room);
}

.group {
  border: 0;
  margin: 0 0 26px;
  padding: 0;
  min-width: 0;
}

.group-title {
  margin: 0 0 12px;
  color: var(--on-room-2);
  font-size: 0.95rem;
}

.step-nav {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 18px;
}

.step-nav .primary {
  flex: 1;
}

/* Controls on the room */

.primary,
.secondary {
  height: 54px;
  padding: 0 24px;
  border: 0;
  border-radius: 999px;
  font-size: 1.02rem;
  font-weight: 600;
  transition: transform 0.15s, background 0.2s;
}

.primary {
  background: var(--chili);
  color: var(--lamp-bright);
}

.primary:hover:not(:disabled) {
  background: var(--chili-deep);
}

.primary:active:not(:disabled) {
  transform: scale(0.985);
}

.primary.block {
  width: 100%;
}

.secondary {
  background: var(--veil);
  color: var(--on-room);
}

.secondary:hover:not(:disabled) {
  background: var(--veil-2);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--veil);
  color: var(--on-room);
  font-size: 0.95rem;
  transition: background 0.2s, color 0.2s;
}

.chip:hover {
  background: var(--veil-2);
}

.chip.on {
  background: var(--lamp);
  color: var(--ink);
}

.add-row {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.field {
  width: 100%;
  min-width: 0;
  height: 48px;
  padding: 0 16px;
  border: 1px solid var(--veil-2);
  border-radius: var(--r-control);
  background: var(--veil);
  color: var(--on-room);
}

.field::placeholder {
  color: var(--on-room-3);
}

.field:focus {
  outline: none;
